import { i18n } from 'src/boot/i18n';
import { notify } from 'src/components/notifications/notify';
import type { dynamicObj } from 'src/pages/assets';
import {
  OPEN_VALIDATION_ASSISTANT_EVENT,
  validationAssistantHost,
} from 'src/utils/validationBlockers';

/** True for "One or more fields need validation", local or from the backend. */
export function isValidationFailure(response: dynamicObj | null | undefined) {
  return (
    response?.needs_validation === true ||
    response?.error_code === 'DOC_NEEDS_VALIDATION'
  );
}

/**
 * CORE-6161: the failure toast, with "Which fields?" opening the validation
 * assistant when the screen has one and the failure is about fields.
 */
export function notifyValidationFailure(
  message: string,
  response?: dynamicObj | null,
) {
  if (!validationAssistantHost.mounted || !isValidationFailure(response)) {
    return notify.error(message);
  }
  return notify.error(message, {
    action: {
      label: i18n.t('validation_assistant_which_fields'),
      onClick: () =>
        document.dispatchEvent(new CustomEvent(OPEN_VALIDATION_ASSISTANT_EVENT)),
    },
  });
}
